param([ValidateSet('build','safety','q7169','q8192')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-streamed-exact-attention-20260917-r2';$seed='D:\projects\AIMA-public-streamed-exact-attention-20260917-r1';$sha='d56ef470738099f15759edd2cbeb3f2dd739294e';$bundle='D:\projects\streamed-exact-attention-d56ef47.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne 'a5f506eea860c5ecb8593322102154c8942d7cde0b0c7291513b5319b201e9a7'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){& git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'};& git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}}
